"use client"

import { useState } from "react"
import { Card, CardContent } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Star, Bookmark, MapPin } from "lucide-react"

export interface Place {
  id: string
  name: string
  description: string
  image: string
  rating: number
  reviewCount: number
  category: string
  location: string
  price?: string
}

interface PlaceCardProps {
  place: Place
  onSelect?: (place: Place) => void
}

export function PlaceCard({ place, onSelect }: PlaceCardProps) {
  const [isBookmarked, setIsBookmarked] = useState(false)

  return (
    <Card
      className="overflow-hidden group cursor-pointer transition-all hover:shadow-lg hover:-translate-y-1"
      onClick={() => onSelect?.(place)}
    >
      <div className="relative h-48 overflow-hidden">
        <img
          src={place.image || "/placeholder.svg"}
          alt={place.name}
          className="w-full h-full object-cover transition-transform group-hover:scale-105"
        />
        <Button
          variant="ghost"
          size="icon"
          className="absolute top-2 right-2 bg-background/80 backdrop-blur-sm hover:bg-background"
          onClick={(e) => {
            e.stopPropagation()
            setIsBookmarked(!isBookmarked)
          }}
        >
          <Bookmark className={`h-4 w-4 ${isBookmarked ? "fill-primary text-primary" : ""}`} />
        </Button>
        <Badge className="absolute bottom-2 left-2" variant="secondary">
          {place.category}
        </Badge>
        {place.price && (
          <Badge className="absolute bottom-2 right-2 bg-background/80 text-foreground">{place.price}</Badge>
        )}
      </div>
      <CardContent className="p-4">
        <div className="flex items-start justify-between mb-2">
          <h3 className="font-semibold line-clamp-1">{place.name}</h3>
          <div className="flex items-center gap-1 text-sm shrink-0">
            <Star className="h-4 w-4 fill-accent text-accent" />
            <span>{place.rating}</span>
            <span className="text-muted-foreground">({place.reviewCount})</span>
          </div>
        </div>
        <div className="flex items-center gap-1 text-sm text-muted-foreground mb-2">
          <MapPin className="h-3 w-3" />
          <span className="line-clamp-1">{place.location}</span>
        </div>
        <p className="text-sm text-muted-foreground line-clamp-2">{place.description}</p>
      </CardContent>
    </Card>
  )
}
